// Port of compiler/rustc_baked_icu_data/src/lib.rs.

//! This crate contains pre-baked ICU4X data, generated by `icu4x-datagen`. The tool
//! fetches locale data from CLDR and transforms them into const code in statics that
//! ICU4X can load, via databake. `lib.rs` in this crate is manually written, but all
//! other code is generated.
//!
//! This crate can be regenerated when there's a new CLDR version, though that is unlikely
//! to result in changes in most cases (currently this only covers list formatting data, which
//! is rather stable). It may need to be regenerated when updating ICU4X versions, especially
//! across major versions, in case it fails to compile after an update.
//!
//! It must be regenerated when adding new locales to Rust, or if Rust's usage of ICU4X
//! grows to need more kinds of data.
//!
//! To regenerate the data, run this command:
//!
//! ```text
//! icu4x-datagen -W --pretty --use-separate-crates \
//! --format baked --locales @en @es @fr @it @ja @pt @ru @tr @zh @zh-Hans @zh-Hant \
//! -m ListAndV1 -o src/data
//! ```
//
// PORT: the data (src/data/*.rs.data) is translated by tools/codegen/icu-data.ts into
// ./data/list_and_v1.ts; the macro-generated provider impl is in ./data/mod.ts.
import type { Result } from "../std/result.ts";
import { type Locale, locale } from "../vendor/icu_locale_core/locale.ts";
import type { DataProvider } from "../vendor/icu_provider/data_provider.ts";
import type { DataError } from "../vendor/icu_provider/error.ts";
import type { DataMarker } from "../vendor/icu_provider/marker.ts";
import type { DataRequest } from "../vendor/icu_provider/request.ts";
import type { DataResponse } from "../vendor/icu_provider/response.ts";
import { load_baked } from "./data/mod.ts";

export class BakedDataProvider implements DataProvider {
  // include!("data/mod.rs");
  // const _: () = { impl_data_provider!(BakedDataProvider); };
  load<T>(marker: DataMarker<T>, req: DataRequest): Result<DataResponse<T>, DataError> {
    return load_baked(marker, req);
  }
}

// rustc: compiler/rustc_baked_icu_data/src/lib.rs:35 baked_data_provider
export function baked_data_provider(): BakedDataProvider {
  return new BakedDataProvider();
}

// PORT: the `locale!` consts are evaluated on first use (module evaluation order).
export const supported_locales = {
  get EN(): Locale {
    return locale("en");
  },
  get ES(): Locale {
    return locale("es");
  },
  get FR(): Locale {
    return locale("fr");
  },
  get IT(): Locale {
    return locale("it");
  },
  get JA(): Locale {
    return locale("ja");
  },
  get PT(): Locale {
    return locale("pt");
  },
  get RU(): Locale {
    return locale("ru");
  },
  get TR(): Locale {
    return locale("tr");
  },
  get ZH_HANS(): Locale {
    return locale("zh-Hans");
  },
  get ZH_HANT(): Locale {
    return locale("zh-Hant");
  },
};


